ROOT=Path(__file__).resolve().parents[1];tests=subprocess.run([sys.executable,"-m","pytest","-q","tests/test_protocols.py"],cwd=ROOT,text=True,capture_output=True);sc=[{"name":"protocol_test_suite","status":"passed" if tests.returncode==0 else "failed","stdout":tests.stdout.strip(),"stderr":tests.stderr.strip()}];demo=subprocess.run([sys.executable,"-m","ailab.protocol_cli","--data",tempfile.mkdtemp()],cwd=ROOT,text=True,capture_output=True);parsed=json.loads(demo.stdout) if demo.returncode==0 else {};sc.append({"name":"integrated_mcp_a2a_demo","status":"passed" if demo.returncode==0 and parsed.get("a2a_task",{}).get("status",{}).get("state")=="completed" else "failed","evidence":parsed,"stderr":demo.stderr});passed=sum(x["status"]=="passed" for x in sc);dest=ROOT/"artifacts/protocol-lab";dest.mkdir(parents=True,exist_ok=True);(dest/"latest.json").write_text(json.dumps({"summary":{"total":len(sc),"passed":passed,"failed":len(sc)-passed},"scenarios":sc},indent=2)+"\n");(dest/"latest.txt").write_text(f"Protocol lab verification: {passed}/{len(sc)} passed\n");print(f"Protocol lab verification: {passed}/{len(sc)} passed");raise SystemExit(0 if passed==len(sc) else 1)
